#!/usr/bin/env python3
"""Apply frozen W0-GATE-2 thresholds without changing them after results."""
from __future__ import annotations
import argparse, json
from pathlib import Path

def load(p):return json.loads(Path(p).read_text()) if p else None
def check(rows,name,value,op,threshold):
    if value is None:status="pending"
    elif op=="max":status="pass" if value<=threshold else "fail"
    elif op=="min":status="pass" if value>=threshold else "fail"
    elif op=="eq":status="pass" if value==threshold else "fail"
    rows.append({"gate":name,"status":status,"measured":value,"operator":op,"threshold":threshold})
def main():
    ap=argparse.ArgumentParser();ap.add_argument("--gates",default="config/gates.w0.json");ap.add_argument("--models");ap.add_argument("--retrieval");ap.add_argument("--embeddings");ap.add_argument("--lifecycle");ap.add_argument("--pairing");ap.add_argument("--revision");ap.add_argument("--soak");ap.add_argument("--output",required=True);args=ap.parse_args();g=load(args.gates);rows=[]
    model=load(args.models);mg=g["model"]
    critical=["prompt-injection-imported-jd","current-record-over-memory","deterministic-analytic-over-feeling-memory","stale-snapshot","fabricated-id-trap","tool-prompt-injection","no-write-tool","health-tool-not-authorized"]
    grounding=["priority-grounding","fabricated-id-trap","cross-domain-conflict"]
    summaries=(model or {}).get("summary",[])
    for s in summaries:
        prefix=f"model:{s.get('candidate')}:{s.get('contextSize')}"
        cold=s.get("coldLoad",{});check(rows,prefix+":cold-load-coverage",cold.get("sufficientCoverage"),"eq",True);check(rows,prefix+":cold-load-samples",cold.get("validSamples"),"min",3);check(rows,prefix+":cold-load-p95",cold.get("p95Ms") if cold.get("sufficientCoverage") else None,"max",mg["startupP95MsMax"]);check(rows,prefix+":ttft-p50",s.get("latencyMs",{}).get("ttft",{}).get("p50"),"max",mg["ttftP50MsMax"]);check(rows,prefix+":ttft-p95",s.get("latencyMs",{}).get("ttft",{}).get("p95"),"max",mg["ttftP95MsMax"]);check(rows,prefix+":tps-p50",s.get("tokensPerSecond",{}).get("p50"),"min",mg["tokensPerSecondP50Min"]);check(rows,prefix+":total-p95",s.get("latencyMs",{}).get("total",{}).get("p95"),"max",mg["totalLatencyP95MsMax"]);check(rows,prefix+":structured",s.get("structured",{}).get("rate"),"min",mg["structuredReliabilityMin"]);check(rows,prefix+":tools",s.get("tools",{}).get("rate"),"min",mg["toolReliabilityMin"])
        scenario=s.get("scenarioReliability",{});critical_rates=[scenario[x]["rate"] for x in critical if x in scenario];ground_rates=[scenario[x]["rate"] for x in grounding if x in scenario]
        check(rows,prefix+":critical-scenarios",min(critical_rates) if len(critical_rates)==len(critical) else None,"min",mg["criticalScenarioReliability"]);check(rows,prefix+":grounding",min(ground_rates) if len(ground_rates)==len(grounding) else None,"min",mg["groundingReliabilityMin"])
        quality=s.get("qualityRates",{});check(rows,prefix+":unsupported-claims",quality.get("unsupportedClaimRate"),"max",mg["unsupportedClaimRateMax"]);check(rows,prefix+":prompt-injection-failures",quality.get("promptInjectionFailureRate"),"max",mg["promptInjectionFailureRateMax"]);check(rows,prefix+":source-precedence",quality.get("sourcePrecedencePassRate"),"min",mg["sourcePrecedenceReliabilityMin"]);check(rows,prefix+":uncertainty",quality.get("uncertaintyPassRate"),"min",mg["uncertaintyReliabilityMin"])
        mem=s.get("memory") or {};gpu=s.get("nvidia") or {};check(rows,prefix+":process-ram",mem.get("peakProcessRssBytes"),"max",mg["processRamBytesMax"]);check(rows,prefix+":system-headroom",mem.get("minimumSystemAvailableBytes"),"min",mg["systemAvailableBytesMin"]);check(rows,prefix+":vram",gpu.get("peakMemoryUsedMiB"),"max",mg["vramPeakMiBMax"]);check(rows,prefix+":temp-p95",gpu.get("p95TemperatureC"),"max",mg["gpuTemperatureP95CMax"]);check(rows,prefix+":temp-max",gpu.get("peakTemperatureC"),"max",mg["gpuTemperatureAbsoluteCMax"]);check(rows,prefix+":shutdown",s.get("shutdownMs"),"max",mg["shutdownMsMax"]);cancel=s.get("cancellation",{});check(rows,prefix+":cancel-ack",cancel.get("cancellationAcknowledged"),"eq",True);check(rows,prefix+":cancel-ack-latency",cancel.get("acknowledgementLatencyMs"),"max",2000);check(rows,prefix+":cancel-termination-latency",cancel.get("requestTerminationLatencyMs"),"max",mg["shutdownMsMax"]);check(rows,prefix+":cancel-terminated",cancel.get("requestTerminated"),"eq",True);check(rows,prefix+":cancel-process-alive",cancel.get("processAlive"),"eq",True);check(rows,prefix+":cancel-orphan-free",cancel.get("orphanFree"),"eq",True);check(rows,prefix+":cancel-active-requests",cancel.get("activeRequestsAfterCancel"),"eq",0);check(rows,prefix+":cancel-vram-recovered",cancel.get("vramRecovered"),"eq",True);check(rows,prefix+":cancel-ram-recovered",cancel.get("ramRecovered"),"eq",True);check(rows,prefix+":cancel-resources-recovered",cancel.get("resourcesRecovered"),"eq",True);check(rows,prefix+":cancel-recovery-window",cancel.get("recoveryWindowSeconds"),"max",mg["resourceRecoverySecondsMax"])
    native={x.get("candidate"):x.get("result",{}) for x in (model or {}).get("nativeBenchmarks",[])}
    for candidate in sorted({x.get("candidate") for x in summaries}):
        check(rows,f"model:{candidate}:llama-bench",native.get(candidate,{}).get("status"),"eq","ok")
        candidate_rows=[x for x in summaries if x.get("candidate")==candidate];base=next((x for x in candidate_rows if x.get("contextSize")==4096),None);large=next((x for x in candidate_rows if x.get("contextSize")==8192),None)
        for context in mg.get("contextSizesRequiredForMeasurement",[4096,8192]):check(rows,f"model:{candidate}:{context}-measured",any(x.get("contextSize")==context for x in candidate_rows),"eq",True)
        base_ttft=(base or {}).get("latencyMs",{}).get("ttft",{}).get("p50");large_ttft=(large or {}).get("latencyMs",{}).get("ttft",{}).get("p50");ratio=large_ttft/base_ttft if base_ttft and large_ttft else None;check(rows,f"model:{candidate}:8k-ttft-ratio",ratio,"max",mg["context8kLatencyRatioMax"])
        for row in candidate_rows:
            prefix=f"model:{candidate}:{row.get('contextSize')}:concurrency2";c={x.get("clients"):x for x in row.get("concurrency",[])};one=c.get(1);two=c.get(2);check(rows,prefix+":coverage",two is not None,"eq",True);check(rows,prefix+":requests",(two or {}).get("total"),"min",2);check(rows,prefix+":failed-requests",(two or {}).get("failedRequests"),"max",0);check(rows,prefix+":structured-coverage",(two or {}).get("structured",{}).get("total"),"min",1);check(rows,prefix+":structured",(two or {}).get("structured",{}).get("rate"),"min",mg["structuredReliabilityMin"]);check(rows,prefix+":tool-coverage",(two or {}).get("tools",{}).get("total"),"min",1);check(rows,prefix+":tools",(two or {}).get("tools",{}).get("rate"),"min",mg["toolReliabilityMin"]);single=(one or {}).get("p95RequestMs");double=(two or {}).get("p95RequestMs");cr=double/single if single and double else None;check(rows,prefix+":latency-ratio",cr,"max",mg["concurrency2LatencyRatioMax"])
    if not model:rows.append({"gate":"model-results","status":"pending","measured":None,"operator":"required","threshold":True})
    retrieval=load(args.retrieval);rg=g["retrieval"];summary=(retrieval or {}).get("passSummary",{});fifty=next((x for x in (retrieval or {}).get("runs",[]) if x.get("records")==50000),{})
    check(rows,"retrieval:hit1",summary.get("minimumHitAt1"),"min",rg["hitAt1Min"]);check(rows,"retrieval:mrr",summary.get("minimumMrrAt10"),"min",rg["mrrAt10Min"]);check(rows,"retrieval:p95-50k",fifty.get("latencyMs",{}).get("p95"),"max",rg["p95At50000MsMax"]);check(rows,"retrieval:filter-leakage",summary.get("filterLeakage"),"max",rg["filterLeakageMax"]);check(rows,"retrieval:deletion",summary.get("allDeletionVerified"),"eq",rg["deletionRequired"])
    emb=load(args.embeddings);eg=g["embeddings"];check(rows,"embedding:hit1",(emb or {}).get("ranking",{}).get("hitAt1"),"min",eg["paraphraseHitAt1Min"]);check(rows,"embedding:mrr",(emb or {}).get("ranking",{}).get("mrr"),"min",eg["mrrMin"]);check(rows,"embedding:latency",(emb or {}).get("queryBatchLatencyMs",{}).get("p95"),"max",eg["queryBatchP95MsMax"])
    soak=load(args.soak);soak_summary=(soak or {}).get("summary",{});soak_gpu=soak_summary.get("nvidia",{});check(rows,"soak:duration",(soak or {}).get("actualDurationSeconds"),"min",1800);check(rows,"soak:throughput-retention",soak_summary.get("finalToInitialThroughputRatio"),"min",.85);check(rows,"soak:temperature-p95",soak_gpu.get("p95TemperatureC"),"max",mg["gpuTemperatureP95CMax"]);check(rows,"soak:temperature-max",soak_gpu.get("peakTemperatureC"),"max",mg["gpuTemperatureAbsoluteCMax"])
    life=load(args.lifecycle);pair=load(args.pairing);rev=load(args.revision);life_summary=(life or {}).get("summary",{});check(rows,"lifecycle:port-release",(life or {}).get("passed"),"eq",True);check(rows,"lifecycle:startup-p95",life_summary.get("startupP95Ms"),"max",mg["startupP95MsMax"]);check(rows,"lifecycle:shutdown-p95",life_summary.get("shutdownP95Ms"),"max",mg["shutdownMsMax"]);check(rows,"pairing:all",(pair or {}).get("passed"),"eq",True);check(rows,"revision:all",(rev or {}).get("passed"),"eq",True)
    counts={x:sum(r["status"]==x for r in rows) for x in ("pass","fail","pending")};overall="fail" if counts["fail"] else "incomplete" if counts["pending"] else "pass"
    out={"schemaVersion":1,"classification":"LOCAL-ONLY-RAW","gateVersion":g["gateVersion"],"overall":overall,"counts":counts,"gates":rows};path=Path(args.output);path.parent.mkdir(parents=True,exist_ok=True);path.write_text(json.dumps(out,indent=2),encoding="utf-8");print(json.dumps({"overall":overall,"counts":counts},indent=2))
if __name__=="__main__":main()
